// ---------------------------------------------------------------------------
// RENDERIZADOR GENÉRICO DE EJERCICIOS
// ---------------------------------------------------------------------------
function Exercise({ item, index, levelColor, onAnswered, t }) {
  const [selected, setSelected] = useState(null);
  const [textVal, setTextVal] = useState("");
  const [checked, setChecked] = useState(false);

  const isCorrect = (val) => {
    if (item.type === "true_false") return val === item.answer;
    if (typeof item.answer === "string") return val.trim().toLowerCase() === item.answer.trim().toLowerCase();
    return val === item.answer;
  };

  const commit = (val) => {
    setSelected(val);
    setChecked(true);
    onAnswered && onAnswered(isCorrect(val));
  };

  const boxStyle = {
    background: "#fff",
    border: `1px solid ${C.line}`,
    borderRadius: 14,
    padding: "16px 18px",
    marginBottom: 14,
  };

  return (
    <div style={boxStyle}>
      <p style={{ fontFamily: bodyFont, color: C.ink, fontSize: 15, marginBottom: 12, lineHeight: 1.5 }}>
        <span style={{ fontFamily: utilFont, color: C.inkSoft, fontSize: 12, marginRight: 8 }}>
          {String(index + 1).padStart(2, "0")}
        </span>
        {item.q}
      </p>

      {item.type === "mcq" && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
          {item.options.map((opt) => {
            const isSel = selected === opt;
            const showGood = checked && isSel && isCorrect(opt);
            const showBad = checked && isSel && !isCorrect(opt);
            return (
              <button
                key={opt}
                onClick={() => !checked && commit(opt)}
                style={{
                  fontFamily: bodyFont,
                  fontSize: 14,
                  padding: "9px 16px",
                  borderRadius: 999,
                  border: `1.5px solid ${showGood ? levelColor.main : showBad ? C.coral : C.line}`,
                  background: showGood ? levelColor.soft : showBad ? C.coralSoft : C.cream,
                  color: showGood ? C.ink : showBad ? C.coralText : C.ink,
                  cursor: checked ? "default" : "pointer",
                  fontWeight: isSel ? 700 : 400,
                }}
              >
                {opt}
              </button>
            );
          })}
        </div>
      )}

      {item.type === "true_false" && (
        <div style={{ display: "flex", gap: 8 }}>
          {[true, false].map((val) => {
            const label = val ? t.trueLabel : t.falseLabel;
            const isSel = selected === val;
            const showGood = checked && isSel && isCorrect(val);
            const showBad = checked && isSel && !isCorrect(val);
            return (
              <button
                key={label}
                onClick={() => !checked && commit(val)}
                style={{
                  fontFamily: bodyFont,
                  fontSize: 14,
                  padding: "9px 20px",
                  borderRadius: 999,
                  border: `1.5px solid ${showGood ? levelColor.main : showBad ? C.coral : C.line}`,
                  background: showGood ? levelColor.soft : showBad ? C.coralSoft : C.cream,
                  color: C.ink,
                  cursor: checked ? "default" : "pointer",
                  fontWeight: isSel ? 700 : 400,
                }}
              >
                {label}
              </button>
            );
          })}
        </div>
      )}

      {item.type === "fill_blank" && (
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <input
            value={textVal}
            disabled={checked}
            onChange={(e) => setTextVal(e.target.value)}
            placeholder={t.typeAnswer}
            style={{
              fontFamily: utilFont,
              fontSize: 14,
              padding: "8px 12px",
              borderRadius: 8,
              border: `1.5px solid ${checked ? (isCorrect(textVal) ? levelColor.main : C.coral) : C.line}`,
              background: checked ? (isCorrect(textVal) ? levelColor.soft : C.coralSoft) : "#fff",
              color: C.ink,
              width: 160,
            }}
          />
          {!checked && (
            <button
              onClick={() => textVal.trim() && commit(textVal)}
              style={{
                fontFamily: bodyFont,
                fontSize: 13,
                padding: "8px 14px",
                borderRadius: 8,
                border: "none",
                background: C.ink,
                color: "#fff",
                cursor: "pointer",
              }}
            >
              {t.check}
            </button>
          )}
          {checked && !isCorrect(textVal) && (
            <span style={{ fontFamily: bodyFont, fontSize: 13, color: C.coralText }}>
              {t.answerLabel}{item.answer}
            </span>
          )}
        </div>
      )}
    </div>
  );
}

