function LessonHeader({ title, subtitle, levelColor, t }) {
  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{ display: "inline-block", background: levelColor.soft, color: C.ink, fontFamily: utilFont, fontSize: 11, padding: "3px 10px", borderRadius: 999, marginBottom: 8, letterSpacing: 1, fontWeight: 700 }}>
        {t.lesson}
      </div>
      <h2 style={{ fontFamily: displayFont, color: C.ink, fontSize: 24, margin: 0, fontWeight: 800 }}>{title}</h2>
      {subtitle && <p style={{ fontFamily: bodyFont, color: C.inkSoft, fontSize: 14, marginTop: 4 }}>{subtitle}</p>}
    </div>
  );
}

function VocabLesson({ unit, levelColor, onComplete, t }) {
  const [idx, setIdx] = useState(0);
  const [flip, setFlip] = useState(false);
  const v = unit.vocabulary[idx];
  const last = idx === unit.vocabulary.length - 1;

  return (
    <div>
      <LessonHeader title={t.lessons.vocab} subtitle={unit.vocab_theme} levelColor={levelColor} t={t} />
      <div
        onClick={() => setFlip((f) => !f)}
        style={{
          background: "#fff",
          border: `1px solid ${C.line}`,
          borderRadius: 18,
          padding: "36px 24px",
          textAlign: "center",
          cursor: "pointer",
          minHeight: 160,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          borderTop: `4px solid ${levelColor.main}`,
        }}
      >
        {!flip ? (
          <p style={{ fontFamily: displayFont, fontSize: 22, color: C.ink, fontWeight: 700 }}>{v.word}</p>
        ) : (
          <>
            <p style={{ fontFamily: displayFont, fontSize: 20, color: C.ink, marginBottom: 8, fontWeight: 700 }}>{v.meaning}</p>
            <p style={{ fontFamily: bodyFont, fontSize: 14, color: C.inkSoft, fontStyle: "italic" }}>"{v.example}"</p>
          </>
        )}
        <p style={{ fontFamily: utilFont, fontSize: 12, color: C.inkSoft, marginTop: 16 }}>
          {flip ? t.tapToSeeWord : t.tapToSeeMeaning}
        </p>
      </div>
      <p style={{ textAlign: "center", fontFamily: utilFont, fontSize: 12, color: C.inkSoft, marginTop: 14 }}>
        {idx + 1} / {unit.vocabulary.length}
      </p>
      <div style={{ display: "flex", gap: 10, marginTop: 16 }}>
        <button
          disabled={idx === 0}
          onClick={() => { setFlip(false); setIdx((i) => i - 1); }}
          style={navBtnStyle(idx === 0)}
        >
          {t.previous}
        </button>
        <button
          onClick={() => {
            if (last) onComplete();
            else { setFlip(false); setIdx((i) => i + 1); }
          }}
          style={{ ...navBtnStyle(false), background: C.ink, color: "#fff", border: "none", flex: 1 }}
        >
          {last ? t.finishLesson : t.next}
        </button>
      </div>
    </div>
  );
}

