function ListeningLesson({ unit, levelColor, onComplete, t }) {
  const l = unit.listening;
  const [played, setPlayed] = useState(false);
  const [answeredCount, setAnsweredCount] = useState(0);
  const total = l.questions.length;

  const play = () => {
    try {
      const utter = new SpeechSynthesisUtterance(l.transcript.replace(/^[AB]:\s*/gm, ""));
      utter.lang = "en-US";
      utter.rate = 0.95;
      window.speechSynthesis.cancel();
      window.speechSynthesis.speak(utter);
    } catch (e) { /* TTS no disponible */ }
    setPlayed(true);
  };

  return (
    <div>
      <LessonHeader title={t.lessons.listening} subtitle={l.title} levelColor={levelColor} t={t} />
      <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 14, padding: 24, marginBottom: 20, textAlign: "center", borderTop: `4px solid ${levelColor.main}` }}>
        <button
          onClick={play}
          style={{ display: "inline-flex", alignItems: "center", gap: 8, fontFamily: bodyFont, fontSize: 14, padding: "12px 22px", borderRadius: 999, border: "none", background: C.ink, color: "#fff", cursor: "pointer" }}
        >
          <Volume2 size={18} /> {played ? t.playAgain : t.playAudio}
        </button>
        {played && (
          <p style={{ fontFamily: bodyFont, fontSize: 12, color: C.inkSoft, marginTop: 14, fontStyle: "italic" }}>
            {t.ttsNote}
          </p>
        )}
      </div>
      {played && l.questions.map((q, i) => (
        <Exercise key={i} item={q} index={i} levelColor={levelColor} t={t} onAnswered={() => setAnsweredCount((c) => Math.min(c + 1, total))} />
      ))}
      {!played && <p style={{ fontFamily: bodyFont, fontSize: 13, color: C.inkSoft, textAlign: "center" }}>{t.playToSeeQuestions}</p>}
      <button
        disabled={answeredCount < total}
        onClick={onComplete}
        style={{ ...navBtnStyle(answeredCount < total), background: answeredCount < total ? C.cream : C.ink, color: answeredCount < total ? C.inkSoft : "#fff", width: "100%", marginTop: 8 }}
      >
        {t.answerQuestions(answeredCount, total)}
      </button>
    </div>
  );
}

function WritingLesson({ unit, levelColor, onComplete, t }) {
  const w = unit.writing;
  const [text, setText] = useState("");
  const [feedback, setFeedback] = useState(null);
  const [loading, setLoading] = useState(false);

  const getFeedback = async () => {
    setLoading(true);
    setFeedback(null);
    try {
      const rubricText = w.rubric.map((r) => `- ${r.criterio}: ${r.descripcion}`).join("\n");
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 1000,
          messages: [
            {
              role: "user",
              content: `Eres profesor de inglés A1 evaluando a un estudiante hispanohablante principiante. Tarea: "${w.prompt}". Rúbrica:\n${rubricText}\n\nRespuesta del estudiante: "${text}"\n\nDa retroalimentación breve en español (máximo 80 palabras): 1) qué hizo bien, 2) un error puntual a corregir si lo hay, 3) una sugerencia. Tono cálido, no uses la palabra "calificación" ni pongas nota numérica.`,
            },
          ],
        }),
      });
      const data = await response.json();
      const textResp = (data.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n");
      setFeedback(textResp || "No se pudo generar retroalimentación en este momento.");
    } catch (e) {
      setFeedback("No se pudo conectar para dar retroalimentación. Puedes seguir de todas formas.");
    }
    setLoading(false);
  };

  return (
    <div>
      <LessonHeader title={t.lessons.writing} subtitle="Written production" levelColor={levelColor} t={t} />
      <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 14, padding: 20, marginBottom: 16, borderTop: `4px solid ${levelColor.main}` }}>
        <p style={{ fontFamily: bodyFont, fontSize: 14, color: C.ink, marginBottom: 14 }}>{w.prompt}</p>
        <textarea
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder={t.writePlaceholder}
          rows={5}
          style={{ width: "100%", fontFamily: bodyFont, fontSize: 14, padding: 12, borderRadius: 10, border: `1px solid ${C.line}`, resize: "vertical", boxSizing: "border-box" }}
        />
        <button
          onClick={getFeedback}
          disabled={!text.trim() || loading}
          style={{ ...navBtnStyle(!text.trim() || loading), background: !text.trim() || loading ? C.cream : C.ink, color: !text.trim() || loading ? C.inkSoft : "#fff", border: "none", marginTop: 10, display: "inline-flex", alignItems: "center", gap: 8 }}
        >
          {loading && <Loader2 size={14} style={{ animation: "spin 1s linear infinite" }} />}
          {loading ? t.reviewing : t.getFeedback}
        </button>
      </div>
      {feedback && (
        <div style={{ background: C.coralSoft, borderRadius: 12, padding: 16, marginBottom: 16 }}>
          <p style={{ fontFamily: bodyFont, fontSize: 13, color: C.ink, lineHeight: 1.6, whiteSpace: "pre-wrap" }}>{feedback}</p>
        </div>
      )}
      <details style={{ marginBottom: 16 }}>
        <summary style={{ fontFamily: bodyFont, fontSize: 13, color: C.inkSoft, cursor: "pointer" }}>{t.viewRubric}</summary>
        <div style={{ marginTop: 10 }}>
          {w.rubric.map((r, i) => (
            <p key={i} style={{ fontFamily: bodyFont, fontSize: 12, color: C.inkSoft, marginBottom: 4 }}>
              <b style={{ color: C.ink }}>{r.criterio}:</b> {r.descripcion}
            </p>
          ))}
        </div>
      </details>
      <button
        disabled={!text.trim()}
        onClick={onComplete}
        style={{ ...navBtnStyle(!text.trim()), background: !text.trim() ? C.cream : C.ink, color: !text.trim() ? C.inkSoft : "#fff", width: "100%" }}
      >
        {t.finishLesson}
      </button>
    </div>
  );
}

function QuizLesson({ unit, levelColor, onComplete, t }) {
  const [correctCount, setCorrectCount] = useState(0);
  const [answeredCount, setAnsweredCount] = useState(0);
  const total = unit.quiz.length;
  const finished = answeredCount >= total;
  const pct = Math.round((correctCount / total) * 100);

  return (
    <div>
      <LessonHeader title={t.quizTitle} subtitle={t.quizSubtitle} levelColor={levelColor} t={t} />
      {!finished && unit.quiz.map((q, i) => (
        <Exercise
          key={i}
          item={q}
          index={i}
          levelColor={levelColor}
          t={t}
          onAnswered={(ok) => {
            setAnsweredCount((c) => c + 1);
            if (ok) setCorrectCount((c) => c + 1);
          }}
        />
      ))}
      {finished && (
        <div style={{ textAlign: "center", padding: "30px 0" }}>
          <Stamp label={unit.level} />
          <p style={{ fontFamily: displayFont, fontSize: 28, color: C.ink, marginTop: 16, fontWeight: 800 }}>{pct}%</p>
          <p style={{ fontFamily: bodyFont, fontSize: 14, color: C.inkSoft, marginBottom: 20 }}>
            {t.correctOutOf(correctCount, total)}
          </p>
          <button onClick={onComplete} style={{ ...navBtnStyle(false), background: C.ink, color: "#fff", padding: "12px 30px" }}>
            {t.backToUnit}
          </button>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// MAPA DE LA UNIDAD (color = color secundario del nivel)
// ---------------------------------------------------------------------------
function UnitMap({ unit, levelColor, progress, onOpenLesson, onBack, t }) {
  const doneCount = LESSONS.filter((l) => progress[l.key]).length;
  const pct = Math.round((doneCount / LESSONS.length) * 100);

  return (
    <div>
      <button onClick={onBack} style={{ display: "inline-flex", alignItems: "center", gap: 6, marginBottom: 18, border: "none", background: "none", padding: 0, color: C.inkSoft, fontFamily: bodyFont, fontSize: 14, cursor: "pointer" }}>
        <ChevronLeft size={16} /> {t.levels}
      </button>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 6 }}>
        <div>
          <span style={{ fontFamily: utilFont, fontSize: 12, color: levelColor.main, letterSpacing: 1, fontWeight: 700 }}>{unit.unit_id}</span>
          <h1 style={{ fontFamily: displayFont, fontSize: 28, color: C.ink, margin: "4px 0", fontWeight: 800 }}>{unit.title}</h1>
          <p style={{ fontFamily: bodyFont, fontSize: 13, color: C.inkSoft }}>{unit.can_do}</p>
        </div>
        <div style={{ position: "relative", width: 52, height: 52, flexShrink: 0 }}>
          <svg width="52" height="52" viewBox="0 0 52 52">
            <circle cx="26" cy="26" r="22" fill="none" stroke={C.line} strokeWidth="5" />
            <circle
              cx="26" cy="26" r="22" fill="none" stroke={levelColor.main} strokeWidth="5"
              strokeDasharray={2 * Math.PI * 22}
              strokeDashoffset={2 * Math.PI * 22 * (1 - pct / 100)}
              strokeLinecap="round"
              transform="rotate(-90 26 26)"
            />
          </svg>
          <span style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: utilFont, fontSize: 12, color: C.ink, fontWeight: 700 }}>
            {pct}%
          </span>
        </div>
      </div>

      <div style={{ marginTop: 30, position: "relative" }}>
        <div style={{ position: "absolute", left: 27, top: 8, bottom: 8, width: 2, background: C.line }} />
        {LESSONS.map((l, i) => {
          const done = progress[l.key];
          const isQuiz = l.key === "quiz";
          const locked = isQuiz ? !LESSONS.slice(0, 5).every((x) => progress[x.key]) : false;
          return (
            <div
              key={l.key}
              onClick={() => !locked && onOpenLesson(l.key)}
              style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 18, cursor: locked ? "default" : "pointer", position: "relative" }}
            >
              <div
                style={{
                  width: 56, height: 56, borderRadius: "50%", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
                  background: done ? C.ink : "#fff",
                  border: `2px solid ${done ? C.ink : locked ? C.line : levelColor.main}`,
                  opacity: locked ? 0.5 : 1,
                  zIndex: 1,
                }}
              >
                {done ? <CheckCircle2 color="#fff" size={24} /> : locked ? <Lock color={C.inkSoft} size={20} /> : <BookOpen color={levelColor.main} size={22} />}
              </div>
              <div>
                <p style={{ fontFamily: bodyFont, fontSize: 15, fontWeight: 600, color: locked ? C.inkSoft : C.ink, margin: 0 }}>{t.lessons[l.key]}</p>
                <p style={{ fontFamily: utilFont, fontSize: 12, color: C.inkSoft, margin: 0 }}>
                  {done ? t.completed : locked ? t.lockedQuiz : t.available}
                </p>
              </div>
            </div>
          );
        })}
      </div>

      {doneCount === LESSONS.length && (
        <div style={{ textAlign: "center", marginTop: 20 }}>
          <Stamp label={unit.level} />
          <p style={{ fontFamily: displayFont, fontSize: 16, color: C.ink, marginTop: 10, fontWeight: 700 }}>{t.unitComplete}</p>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// PANTALLA DE NIVELES (con logo Tweetalig y colores secundarios por nivel)
// ---------------------------------------------------------------------------
function LevelsScreen({ onOpenUnit, t }) {
  const [expanded, setExpanded] = useState(null);
  return (
    <div>
      <div style={{ textAlign: "center", marginBottom: 8 }}>
        <img src={LOGO_SRC} alt="Tweetalig" style={{ height: 44, marginBottom: 18 }} />
      </div>
      <h1 style={{ fontFamily: displayFont, fontSize: 30, color: C.ink, marginBottom: 4, fontWeight: 800, textAlign: "center" }}>Tweetaform</h1>
      <p style={{ fontFamily: bodyFont, fontSize: 14, color: C.inkSoft, marginBottom: 28, textAlign: "center" }}>{t.appTagline}</p>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 20 }}>
        {LEVELS.map((lvl) => {
          const lc = LEVEL_COLORS[lvl.code];
          const isOpen = expanded === lvl.code;
          return (
            <div
              key={lvl.code}
              onClick={() => setExpanded(isOpen ? null : lvl.code)}
              style={{
                background: "#fff",
                border: `1.5px solid ${isOpen ? C.ink : C.line}`,
                borderTop: `5px solid ${lc.main}`,
                borderRadius: 14,
                padding: "18px 14px",
                cursor: "pointer",
                textAlign: "center",
              }}
            >
              <p style={{ fontFamily: displayFont, fontSize: 22, color: C.ink, fontWeight: 800, margin: 0 }}>{lvl.code}</p>
              <p style={{ fontFamily: utilFont, fontSize: 11, color: C.inkSoft, margin: "4px 0 0" }}>{t.unitsCount(lvl.units.length)}</p>
            </div>
          );
        })}
      </div>

      {expanded && (() => {
        const lvl = LEVELS.find((l) => l.code === expanded);
        const lc = LEVEL_COLORS[lvl.code];
        return (
          <div style={{ marginBottom: 10 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
              <span style={{ fontFamily: utilFont, fontSize: 13, fontWeight: 700, color: "#fff", background: C.ink, borderRadius: 6, padding: "3px 10px", borderBottom: `3px solid ${lc.main}` }}>{lvl.code}</span>
              <div style={{ flex: 1, height: 1, background: C.line }} />
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {lvl.units.map((u, i) => {
                const enabled = i === 0; // primera unidad de cada nivel ya tiene contenido completo
                return (
                  <div
                    key={u}
                    onClick={() => enabled && onOpenUnit(lvl.code)}
                    style={{
                      display: "flex", alignItems: "center", justifyContent: "space-between",
                      background: "#fff", border: `1px solid ${C.line}`, borderRadius: 12,
                      borderLeft: `4px solid ${lc.main}`,
                      padding: "14px 16px", cursor: enabled ? "pointer" : "default", opacity: enabled ? 1 : 0.55,
                    }}
                  >
                    <span style={{ fontFamily: bodyFont, fontSize: 14, color: C.ink }}>
                      <span style={{ fontFamily: utilFont, color: C.inkSoft, fontSize: 12, marginRight: 8 }}>{i + 1}</span>
                      {u}
                    </span>
                    {enabled ? <BookOpen size={16} color={lc.main} /> : <Lock size={16} color={C.inkSoft} />}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })()}
    </div>
  );
}

// ---------------------------------------------------------------------------
// APP
// ---------------------------------------------------------------------------
export default function App() {
  const [screen, setScreen] = useState("levels"); // levels | unit | lesson
  const [activeLevel, setActiveLevel] = useState("A1");
  const [activeLesson, setActiveLesson] = useState(null);
  const [progressByLevel, setProgressByLevel] = useState({});
  const [lang, setLang] = useState("en");
  const t = STRINGS[lang];

  const unit = UNITS_BY_LEVEL[activeLevel];
  const levelColor = LEVEL_COLORS[unit.level];
  const progress = progressByLevel[activeLevel] || {};

  const markComplete = (key) => {
    setProgressByLevel((p) => ({ ...p, [activeLevel]: { ...(p[activeLevel] || {}), [key]: true } }));
    setScreen("unit");
    setActiveLesson(null);
  };

  const renderLesson = () => {
    const props = { unit, levelColor, t, onComplete: () => markComplete(activeLesson) };
    switch (activeLesson) {
      case "vocab": return <VocabLesson {...props} />;
      case "grammar": return <GrammarLesson {...props} />;
      case "reading": return <ReadingLesson {...props} />;
      case "listening": return <ListeningLesson {...props} />;
      case "writing": return <WritingLesson {...props} />;
      case "quiz": return <QuizLesson {...props} />;
      default: return null;
    }
  };

  return (
    <div style={{ background: C.bg, minHeight: "100vh", padding: "24px 18px", boxSizing: "border-box", position: "relative" }}>
      <FontImport />
      <button
        onClick={() => setLang((l) => (l === "en" ? "es" : "en"))}
        style={{
          position: "absolute", top: 18, right: 18, fontFamily: utilFont, fontSize: 12, fontWeight: 700,
          padding: "6px 12px", borderRadius: 999, border: `1px solid ${C.line}`, background: "#fff", color: C.ink, cursor: "pointer", zIndex: 10,
        }}
      >
        {lang === "en" ? "Ver en español" : "View in English"}
      </button>
      <div style={{ maxWidth: 460, margin: "0 auto" }}>
        {screen === "levels" && <LevelsScreen t={t} onOpenUnit={(code) => { setActiveLevel(code); setScreen("unit"); }} />}
        {screen === "unit" && (
          <UnitMap
            unit={unit}
            levelColor={levelColor}
            progress={progress}
            t={t}
            onOpenLesson={(key) => { setActiveLesson(key); setScreen("lesson"); }}
            onBack={() => setScreen("levels")}
          />
        )}
        {screen === "lesson" && (
          <div>
            <button
              onClick={() => setScreen("unit")}
              style={{ display: "inline-flex", alignItems: "center", gap: 6, marginBottom: 16, border: "none", background: "none", padding: 0, color: C.inkSoft, fontFamily: bodyFont, fontSize: 14, cursor: "pointer" }}
            >
              <ChevronLeft size={16} /> {unit.title}
            </button>
            {renderLesson()}
          </div>
        )}
      </div>
    </div>
  );
}
